module PlayerIdentity
  extend ActiveSupport::Concern

  COOKIE = :quizzy_players

  private
    def player_tokens
      raw = cookies.signed[COOKIE]
      return {} unless raw.is_a?(Hash)

      raw.to_h.each_with_object({}) do |(key, value), tokens|
        tokens[key.to_s] = value.to_s
      end
    end

    def remember_player!(player)
      tokens = player_tokens.merge(player.game.code => player.token)
      cookies.signed[COOKIE] = {
        value: tokens,
        httponly: true,
        same_site: :lax,
        secure: false,
        expires: 1.day.from_now
      }
    end

    def current_player_for(game)
      token = player_tokens[game.code]
      return nil if token.blank?

      game.players.find_by(token: token)
    end
end
