cat > /app/app/controllers/plays_controller.rb << 'EOF'
class PlaysController < ApplicationController
  include PlayerIdentity

  before_action :set_game
  before_action :set_player
  before_action :no_store

  def show
    prepare
  end

  def state
    prepare
    render json: player_payload(include_html: params[:phase_key] != @screen.phase_key)
  end

  def join
    if @player || @game.finished?
      redirect_to play_path(@game.code)
      return
    end

    player = @game.enroll!(params[:name])
    if player
      remember_player!(player)
      redirect_to play_path(@game.code)
    elsif @game.reload.finished?
      redirect_to play_path(@game.code)
    else
      @join_error = "Enter your name to join."
      prepare
      render :show, status: :unprocessable_entity
    end
  end

  def answer
    option = Option.find_by(id: params[:option_id])
    @game.accept_answer!(@player, option) if @player && option
    @game.reload
    prepare
    respond_to do |format|
      format.html { redirect_to play_path(@game.code) }
      format.json { render json: player_payload(include_html: true) }
    end
  end

  private
    def set_game
      @game = Game.find_by!(code: params[:code].to_s.upcase)
    end

    def set_player
      @player = current_player_for(@game)
    end

    def prepare
      @quiz = @game.quiz
      @screen = PlayerScreen.new(@game, player: @player)
    end

    def player_payload(include_html:)
      payload = {
        version: @game.version,
        phase: @screen.phase_key,
        phase_key: @screen.phase_key,
        counters: {}
      }
      payload[:body_html] = fragment("body") if include_html
      payload
    end

    def fragment(partial)
      render_to_string(partial: partial, formats: [ :html ], layout: false)
    ensure
      response.content_type = nil
    end

    def no_store
      response.headers["Cache-Control"] = "private, no-store, max-age=0, must-revalidate"
      response.headers["Pragma"] = "no-cache"
      response.headers["Vary"] = "Cookie"
    end
end
